// TH14 v1.00b st02.ecl::MainSub02 (lines 665-680) and closure.
// Source frame 0 = first MainSub02 instruction; card frame 0 = phase_begin (120-frame opening buffer).
// Diffs: chapter/drop/anm/birth stage omitted; no DPS shell, so GirlA01 L-only setDeath is unreachable.

const TIME_LIMIT: int = 2324;       // 120 opening + 2200 schedule/tail estimate + 4 startup.
const OPENING_BUFFER: int = 120;

// Source etExSet(type 2, a=1): birth ANIM applies position -= 4*velocity. Birth stage is omitted
// but this entry displacement is kept (ex-effects.md); firing code spawns the bullet already shifted.
xformdef ACCEL_DOWN(accel: fx, dir: angle) {
    // Source etExSet(0,1,0,4,120,-999999,<rank scalar>,%A): ACCEL a=120, fixed direction s.
    set_gravity(accel * cos(dir), accel * sin(dir));
    wait(120);
    set_gravity(0fx, 0fx);
}

// GirlA01_at (st02.ecl 157-203), async only for !NHL. One aimed BALL2 per wave.
async sub girl_a01_at() {
    var rank: int = global(GVAR_RANK);
    // Source $RAND%300 for E/N, $RAND%60 for H/L (drawn once at sub start).
    var delay: int = 60;
    if rank <= 1 { delay = 300; }
    wait(rand(delay));
    // diffI($A,1,1,5,10) shot count; speed 1.2/1.2/2.4/4.0; wait 30 E/N else 60.
    var shots: int = 5;
    var speed: fx = 2.4fx;
    var interval: int = 60;
    if rank == 1 { shots = 1; speed = 1.2fx; interval = 30; }
    if rank == 3 { shots = 10; speed = 4fx; }
    var back: fx = 4fx * speed; // source ANIM a=1: -4*velocity.
    for i in 0..shots {
        var a: angle = aim_player(); // source etAim(0,0), N=1, alpha=0.
        _ = fire(TH14_BALL2, 6, $self_x - back * cos(a), $self_y - back * sin(a),
                 speed, a, none, none);
        wait(interval);
    }
}

// GirlA01 (st02.ecl 135-155). Created mirror=1 on the right (enmCreateM) and mirror=0 left.
// Mirror reflects the stored angle across x: right runs 157.5deg (pi-22.5deg); moveAngleTime
// mode7 adds +1deg/frame to the stored angle, so the mirrored world turn is -1deg/frame.
async sub girl_a01(start: angle, turn: angle) {
    set_invuln(65535);
    set_hurtbox(12fx); // source 24.0
    set_hitbox(8fx);   // source 16.0
    // Source moveVel(0.3926991f, 2.2f), mirror applied.
    move_vel(0, start, 2.2fx, EASE_LINEAR);
    if global(GVAR_RANK) >= 1 { spawn girl_a01_at(); }
    wait(120);
    // Source moveAngleTime(140, 7, 0.017453292f): mode7 +1deg per update.
    move_angle(140, $self_angle + turn, EASE_LINEAR);
    wait(140);
    loop { wait(1000); }
}

// GirlD01_at (st02.ecl 435-475). One BIG_BALL per wave, 100 waves.
async sub girl_d01_at() {
    var rank: int = global(GVAR_RANK);
    // wait 100/40/20/10 between waves.
    var interval: int = 20;
    if rank == 0 { interval = 100; }
    if rank == 1 { interval = 40; }
    if rank == 3 { interval = 10; }
    // ACCEL scalar r: 0.02/0.028333/0.031667/0.036667.
    var accel: fx = 0.031667fx;
    if rank == 0 { accel = 0.02fx; }
    if rank == 1 { accel = 0.028333fx; }
    if rank == 3 { accel = 0.036667fx; }
    for i in 0..100 {
        // Source order: RANDRAD for ACCEL direction s, then RANDRAD for firing angle.
        // s = pi/2 + RANDRAD/6 (pm30deg); angle = -pi/2 + RANDRAD/8 (pm22.5deg).
        var sdir: angle = (16384 + (rand(65536) - 32768) / 6) as angle;
        var a: angle = (-16384 + (rand(65536) - 32768) / 8) as angle;
        // ANIM a=1 with speed 1.0: -4px along the bullet angle.
        _ = fire(TH14_BIG_BALL, 3, $self_x - 4fx * cos(a), $self_y - 4fx * sin(a),
                 1fx, a, ACCEL_DOWN(accel, sdir), none);
        wait(interval);
    }
}

// GirlD01 (st02.ecl 413-433). Right one via enmCreateM (mirror), left via enmCreate.
async sub girl_d01(start: angle) {
    set_invuln(65535);
    move_vel(0, start, 3fx, EASE_LINEAR);   // source moveVel(0.3926991f, 3.0f)
    move_speed(60, 0.6fx, EASE_LINEAR);     // source moveSpeedTime(60, 0, 0.6f)
    set_hurtbox(16fx);                      // source 32.0
    set_hitbox(12fx);                       // source 24.0
    wait(60);
    spawn girl_d01_at();
    loop { wait(1000); }
}

// MainSub02b (682-696): async left side, starts at source frame 100.
async sub schedule_left() {
    wait(100);
    for i in 0..6 {
        _ = spawn_enemy(-192fx, -32fx, 120, 0, 1000, 0, girl_a01(4096bam, 140deg));
        wait(20);
        _ = spawn_enemy(-192fx, -32fx, 120, 0, 1000, 0, girl_a01(4096bam, 140deg));
        wait(20);
    }
}

// MainSub02c (698-705): D01 at +224 (mirror) frame 100, -224 (plain) frame 300.
async sub schedule_d01() {
    wait(100);
    _ = spawn_enemy(224fx, 32fx, 800, 0, 1000, 0, girl_d01(28672bam));
    wait(200);
    _ = spawn_enemy(-224fx, 64fx, 800, 0, 1000, 0, girl_d01(4096bam));
}

// MainSub02 (665-680): right side at frame 0, red then blue every 20, six groups.
async sub pattern() {
    wait(OPENING_BUFFER);
    spawn schedule_left();
    spawn schedule_d01();
    for i in 0..6 {
        _ = spawn_enemy(192fx, -32fx, 120, 0, 1000, 0, girl_a01(28672bam, -140deg));
        wait(20);
        _ = spawn_enemy(192fx, -32fx, 120, 0, 1000, 0, girl_a01(28672bam, -140deg));
        wait(20);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

